#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>

#include <zephyr/kernel.h>
#include <zephyr/arch/cpu.h>
#include <zephyr/sys/printk.h>
#include <zephyr/sys/reboot.h>

#include "iree/base/api.h"
#include "iree/hal/api.h"
#include "iree/hal/device_group.h"
#include "iree/hal/local/loaders/merlin_gemmini_counter.h"
#include "iree/modules/hal/module.h"
#include "iree/vm/api.h"
#include "iree/vm/bytecode/module.h"

#include "model_info.h"

#ifndef MERLIN_BACKEND
#define MERLIN_BACKEND "unknown"
#endif
#ifndef MERLIN_HART
#define MERLIN_HART 0
#endif
#ifndef MERLIN_NEEDS_VECTOR
#define MERLIN_NEEDS_VECTOR 0
#endif
#if defined(MERLIN_MODEL_MLP_WIDE)
#define MERLIN_MODEL_NAME "mlp_wide"
#elif defined(MERLIN_MODEL_DRONET)
#define MERLIN_MODEL_NAME "dronet"
#elif defined(MERLIN_MODEL_YOLOV8N)
#define MERLIN_MODEL_NAME "yolov8n"
#else
#define MERLIN_MODEL_NAME "unknown"
#endif

/* Provided by device_stubs.c. */
extern iree_status_t create_sample_device(iree_allocator_t host_allocator,
                                          iree_hal_device_t** out_device);
extern const iree_const_byte_span_t load_bytecode_module_data(void);

/* ---------- helpers ---------- */

static inline uint64_t rdmcycle(void) {
  uint64_t c;
  __asm__ __volatile__("csrr %0, mcycle\n" : "=r"(c));
  return c;
}

/* ---------- phase instrumentation ----------
 * Capture rdmcycle at well-defined boundaries so we can show how the
 * inference wall splits across (Zephyr boot, IREE module init, HAL device
 * setup, dispatch execution, output teardown). Stamps go into a static
 * array; we print one batched summary at end-of-main so the HTIF UART
 * cost (~30 Mcycles/line) shows up exactly once and doesn't pollute the
 * deltas being measured.
 *
 * Boundary stamps (added BEFORE the named operation completes; delta to
 * the next stamp is the operation's cost):
 */
typedef enum {
  PHASE_MAIN_ENTRY,            /* 0  → boot+zephyr_init */
  PHASE_WORKER_STARTED,        /* 1  → spawn+pin overhead */
  PHASE_RUN_INFERENCE_ENTRY,   /* 2  */
  PHASE_VM_INSTANCE_CREATED,   /* 3  */
  PHASE_DEVICE_CREATED,        /* 4  */
  PHASE_DEVICE_GROUP_CREATED,  /* 5  */
  PHASE_HAL_MODULE_CREATED,    /* 6  */
  PHASE_BYTECODE_MODULE_CREATED, /* 7 */
  PHASE_CONTEXT_CREATED,       /* 8  */
  PHASE_FUNCTION_RESOLVED,     /* 9  */
  PHASE_INPUTS_BUILT,          /* 10 */
  PHASE_OUTPUTS_LIST_CREATED,  /* 11 */
  PHASE_INVOKE_T0,             /* 12 → entire IREE bytecode invoke + dispatches */
  PHASE_INVOKE_T1,             /* 13 */
  PHASE_OUTPUTS_HASHED,        /* 14 → d2h + fnv1a hashing */
  PHASE_RUN_INFERENCE_EXIT,    /* 15 */
  PHASE_MAIN_EXIT,             /* 16 */
  PHASE__COUNT,
} merlin_phase_t;

static const char* const k_phase_name[PHASE__COUNT] = {
    "main_entry", "worker_started", "run_inference_entry",
    "vm_instance_created", "device_created", "device_group_created",
    "hal_module_created", "bytecode_module_created", "context_created",
    "function_resolved", "inputs_built", "outputs_list_created",
    "invoke_t0", "invoke_t1", "outputs_hashed", "run_inference_exit",
    "main_exit",
};

static uint64_t g_phase_stamp[PHASE__COUNT];

static inline void merlin_phase_stamp(merlin_phase_t p) {
  g_phase_stamp[p] = rdmcycle();
}

static void merlin_phase_dump(void) {
  /* Print one line per BOUNDARY-TO-BOUNDARY delta plus the absolute
   * timestamps (so a parser can verify monotonicity). One batched output
   * block; this paid for itself once via HTIF UART. */
  printf("[phase] === Merlin phase summary ===\n");
  for (int i = 0; i < PHASE__COUNT; ++i) {
    if (g_phase_stamp[i] == 0 && i != PHASE_MAIN_ENTRY) continue;
    uint64_t delta = 0;
    if (i > 0 && g_phase_stamp[i] > 0 && g_phase_stamp[i - 1] > 0) {
      delta = g_phase_stamp[i] - g_phase_stamp[i - 1];
    }
    printf("[phase] %2d %-26s abs=%llu delta_from_prev=%llu\n",
           i, k_phase_name[i],
           (unsigned long long)g_phase_stamp[i],
           (unsigned long long)delta);
  }
  /* Highlight the inference itself separately. */
  uint64_t inv = g_phase_stamp[PHASE_INVOKE_T1] - g_phase_stamp[PHASE_INVOKE_T0];
  uint64_t total = g_phase_stamp[PHASE_MAIN_EXIT] - g_phase_stamp[PHASE_MAIN_ENTRY];
  printf("[phase] invoke_cycles=%llu  main_cycles=%llu  invoke_frac=%llu/1000\n",
         (unsigned long long)inv, (unsigned long long)total,
         total ? (unsigned long long)((inv * 1000ULL) / total) : 0ULL);
}

/* Per-dispatch cycle log fed by embedded_elf_loader.c. Captured during
 * inference into static memory (no HTIF per-dispatch). Dumped once here. */
typedef struct {
  uint32_t ordinal;
  uint32_t wg_x;
  uint32_t wg_y;
  uint32_t wg_z;
  uint64_t cycles;
  int32_t ret;
  int32_t _pad;
} merlin_dispatch_log_entry_t;

extern merlin_dispatch_log_entry_t merlin_dispatch_log[];
extern uint32_t merlin_dispatch_log_count;

static void merlin_dispatch_dump(void) {
  printf("[disp] === per-dispatch cycle log (n=%u) ===\n",
         (unsigned)merlin_dispatch_log_count);
  uint64_t sum = 0;
  for (uint32_t i = 0; i < merlin_dispatch_log_count; ++i) {
    const merlin_dispatch_log_entry_t* e = &merlin_dispatch_log[i];
    printf("[disp] ord=%u wg=(%u,%u,%u) cycles=%llu ret=%d\n",
           (unsigned)e->ordinal,
           (unsigned)e->wg_x, (unsigned)e->wg_y, (unsigned)e->wg_z,
           (unsigned long long)e->cycles, (int)e->ret);
    sum += e->cycles;
  }
  printf("[disp] dispatch_cycles_total=%llu\n", (unsigned long long)sum);
}

/* FNV-1a 64-bit over a byte span; deterministic across backends so we can
 * cross-check output identity. */
static uint64_t fnv1a64(const void* data, size_t len) {
  const uint8_t* p = (const uint8_t*)data;
  uint64_t h = 0xcbf29ce484222325ULL;
  for (size_t i = 0; i < len; ++i) {
    h ^= (uint64_t)p[i];
    h *= 0x100000001b3ULL;
  }
  return h;
}

static inline void set_vs_dirty(void) {
  /* lesson 4: enable mstatus.VS so per-hart vector ops don't trap when the
   * Zephyr global config has CONFIG_RISCV_ISA_EXT_V=n.
   *
   * lesson 5 (2026-05-25): ALSO set mstatus.XS=Dirty. Zephyr's reset.S sets
   * FS and VS but NOT XS. Non-LOOP_WS Gemmini opcodes (MVIN/MVOUT/...) appear
   * to bypass the XS gate, but LOOP_WS opcodes (used by the Phase-8 bulk
   * matmul path) require XS=Dirty or the FireSim Shuttle Gemmini hangs.
   * Verified via zephyr_gemmini_canonical_test which calls gemmini-rocc-tests
   * tiled_matmul_auto(WS) — works at 2803 cycles for 64x64x64 with XS=Dirty,
   * hangs forever without.
   */
  unsigned long bits = (3UL << 9) | (3UL << 15);  /* VS=Dirty | XS=Dirty */
  __asm__ __volatile__("csrs mstatus, %0" :: "r"(bits));
}

#define IREE_CHECK(expr, what)                                            \
  do {                                                                    \
    iree_status_t _s = (expr);                                            \
    if (!iree_status_is_ok(_s)) {                                         \
      printf("[merlin] FAIL at %s\n", (what));                            \
      iree_status_fprint(stderr, _s);                                     \
      iree_status_free(_s);                                               \
      return -1;                                                          \
    }                                                                     \
  } while (0)

/* ---------- run one inference ---------- */

static int run_inference(uint64_t* out_cycles, uint64_t* out_hash) {
  merlin_phase_stamp(PHASE_RUN_INFERENCE_ENTRY);
  /* 2026-05-23: dispatch_debug stays OFF for fast profiling — per-call
   * UART prints ([dn]/[dc]/[entry]/[bcontent]/[bprobe]/[binding]) saturate
   * FireSim's slow buffered HTIF and dominate wall time (yolov8n × scalar
   * was 2h25min model + 30min dispatch-log dump in the chatty variant).
   * Symbol names are still captured silently into iree_merlin_sym_per_ordinal[]
   * by the loader and emitted once at end via iree_merlin_dump_cycles(). */
  iree_allocator_t host_allocator = iree_allocator_system();

  iree_vm_instance_t* instance = NULL;
  IREE_CHECK(iree_vm_instance_create(IREE_VM_TYPE_CAPACITY_DEFAULT,
                                     host_allocator, &instance),
             "vm_instance_create");
  IREE_CHECK(iree_hal_module_register_all_types(instance),
             "hal_register_types");
  printk("[rinf] B vm_instance ok\n");
  merlin_phase_stamp(PHASE_VM_INSTANCE_CREATED);

  iree_hal_device_t* device = NULL;
  IREE_CHECK(create_sample_device(host_allocator, &device),
             "create_sample_device");
  printk("[rinf] C device ok\n");
  merlin_phase_stamp(PHASE_DEVICE_CREATED);

  iree_hal_device_group_t* device_group = NULL;
  IREE_CHECK(iree_hal_device_group_create_from_device(
                 device, host_allocator, &device_group),
             "device_group_create_from_device");
  printk("[rinf] D device_group ok\n");
  merlin_phase_stamp(PHASE_DEVICE_GROUP_CREATED);

  iree_vm_module_t* hal_module = NULL;
  IREE_CHECK(iree_hal_module_create(
                 instance, iree_hal_module_device_policy_default(),
                 device_group, IREE_HAL_MODULE_FLAG_SYNCHRONOUS,
                 iree_hal_module_debug_sink_null(), host_allocator,
                 &hal_module),
             "hal_module_create");
  printk("[rinf] E hal_module ok\n");
  merlin_phase_stamp(PHASE_HAL_MODULE_CREATED);

  const iree_const_byte_span_t module_data = load_bytecode_module_data();
  printk("[rinf] F module_data size=%zu\n", module_data.data_length);

  iree_vm_module_t* bytecode_module = NULL;
  IREE_CHECK(iree_vm_bytecode_module_create(
                 instance, IREE_VM_BYTECODE_MODULE_FLAG_NONE, module_data,
                 iree_allocator_null(), host_allocator, &bytecode_module),
             "vm_bytecode_module_create");
  printk("[rinf] G bytecode_module ok\n");
  merlin_phase_stamp(PHASE_BYTECODE_MODULE_CREATED);

  iree_vm_context_t* context = NULL;
  iree_vm_module_t* modules[] = {hal_module, bytecode_module};
  IREE_CHECK(iree_vm_context_create_with_modules(
                 instance, IREE_VM_CONTEXT_FLAG_NONE, IREE_ARRAYSIZE(modules),
                 &modules[0], host_allocator, &context),
             "vm_context_create");
  printk("[rinf] H context ok\n");
  merlin_phase_stamp(PHASE_CONTEXT_CREATED);
  iree_vm_module_release(hal_module);
  iree_vm_module_release(bytecode_module);

  iree_vm_function_t main_function;
/* [bp] startup print stripped 2026-05-23 */
  IREE_CHECK(iree_vm_context_resolve_function(
                 context, iree_make_cstring_view(MERLIN_ENTRY_FUNCTION_NAME),
                 &main_function),
             "resolve_function");
  printk("[rinf] I function resolved\n");
  merlin_phase_stamp(PHASE_FUNCTION_RESOLVED);

  /* Build inputs: one or more zero-filled tensors per merlin_inputs[]. */
  iree_vm_list_t* inputs = NULL;
  IREE_CHECK(iree_vm_list_create(iree_vm_make_undefined_type_def(),
                                 MERLIN_INPUT_COUNT, host_allocator, &inputs),
             "inputs_list_create");

  for (int i = 0; i < MERLIN_INPUT_COUNT; ++i) {
    const merlin_tensor_spec_t* spec = &merlin_inputs[i];
    void* zero_buf = calloc(1, spec->byte_count);
    if (!zero_buf) {
      printf("[merlin] FAIL: calloc(%zu) for input %d\n",
             spec->byte_count, i);
      return -1;
    }
    iree_hal_buffer_view_t* bv = NULL;
    iree_status_t s = iree_hal_buffer_view_allocate_buffer_copy(
        device, iree_hal_device_allocator(device), spec->rank, spec->shape,
        spec->element_type, IREE_HAL_ENCODING_TYPE_DENSE_ROW_MAJOR,
        (iree_hal_buffer_params_t){
            .type = IREE_HAL_MEMORY_TYPE_DEVICE_LOCAL,
            .usage = IREE_HAL_BUFFER_USAGE_DEFAULT,
        },
        iree_make_const_byte_span(zero_buf, spec->byte_count), &bv);
    free(zero_buf);
    if (!iree_status_is_ok(s)) {
      printf("[merlin] FAIL upload input %d\n", i);
      iree_status_fprint(stderr, s);
      iree_status_free(s);
      return -1;
    }
    iree_vm_ref_t ref = iree_hal_buffer_view_move_ref(bv);
    IREE_CHECK(iree_vm_list_push_ref_move(inputs, &ref), "push_input");
  }
  merlin_phase_stamp(PHASE_INPUTS_BUILT);

  iree_vm_list_t* outputs = NULL;
  IREE_CHECK(iree_vm_list_create(iree_vm_make_undefined_type_def(),
                                 MERLIN_OUTPUT_COUNT, host_allocator,
                                 &outputs),
             "outputs_list_create");
  merlin_phase_stamp(PHASE_OUTPUTS_LIST_CREATED);

/* invoking print stripped 2026-05-23 */
  /* 2026-05-24: always irq_lock during invoke, not only for RVV paths.
   * Zephyr's tick timer fires at CONFIG_SYS_CLOCK_TICKS_PER_SEC and each
   * ISR + context-switch adds a few kcycles of jitter to the measured
   * cycle count. The worker thread is cooperatively scheduled and the
   * fence rw,rw in embedded_elf_loader handles all Gemmini DMA coherency,
   * so suppressing ticks is safe for all backends. set_vs_dirty() is also
   * harmless on non-V configs (the VS bits are WARL no-ops there). */
  set_vs_dirty();
  unsigned int irq_key = irq_lock();
  set_vs_dirty();  /* re-arm after irq_lock in case it touched mstatus */
  printk("[rinf] J pre invoke\n");
  uint64_t t0 = rdmcycle();
  merlin_phase_stamp(PHASE_INVOKE_T0);
  iree_status_t invoke_status =
      iree_vm_invoke(context, main_function, IREE_VM_INVOCATION_FLAG_NONE,
                     /*policy=*/NULL, inputs, outputs, host_allocator);
  uint64_t t1 = rdmcycle();
  merlin_phase_stamp(PHASE_INVOKE_T1);
  irq_unlock(irq_key);
  printk("[rinf] K post invoke ok=%d\n", iree_status_is_ok(invoke_status));
  if (!iree_status_is_ok(invoke_status)) {
    printf("[merlin] FAIL vm_invoke\n");
    iree_status_fprint(stderr, invoke_status);
    iree_status_free(invoke_status);
    return -1;
  }
  *out_cycles = t1 - t0;

  /* Pull every output back to the host, accumulate one rolling FNV-1a hash. */
  uint64_t hash = 0xcbf29ce484222325ULL;
  for (int i = 0; i < MERLIN_OUTPUT_COUNT; ++i) {
    iree_hal_buffer_view_t* bv =
        iree_vm_list_get_buffer_view_assign(outputs, i);
    if (!bv) {
      printf("[merlin] FAIL: missing output %d\n", i);
      return -1;
    }
    const merlin_tensor_spec_t* spec = &merlin_outputs[i];
    void* host_buf = malloc(spec->byte_count);
    if (!host_buf) {
      printf("[merlin] FAIL: malloc(%zu) for output %d\n",
             spec->byte_count, i);
      return -1;
    }
    iree_status_t s = iree_hal_device_transfer_d2h(
        device, iree_hal_buffer_view_buffer(bv), 0, host_buf,
        spec->byte_count, IREE_HAL_TRANSFER_BUFFER_FLAG_DEFAULT,
        iree_infinite_timeout());
    if (!iree_status_is_ok(s)) {
      free(host_buf);
      printf("[merlin] FAIL d2h transfer output %d\n", i);
      iree_status_fprint(stderr, s);
      iree_status_free(s);
      return -1;
    }
    /* Mix per-output FNV-1a into the running hash. */
    uint64_t h_i = fnv1a64(host_buf, spec->byte_count);
    hash ^= h_i + 0x9e3779b97f4a7c15ULL + (hash << 6) + (hash >> 2);
    free(host_buf);
  }
  *out_hash = hash;
  merlin_phase_stamp(PHASE_OUTPUTS_HASHED);

  iree_vm_list_release(inputs);
  iree_vm_list_release(outputs);
  iree_hal_device_group_release(device_group);
  iree_hal_device_release(device);
  iree_vm_context_release(context);
  iree_vm_instance_release(instance);
  merlin_phase_stamp(PHASE_RUN_INFERENCE_EXIT);
  return 0;
}

/* ---------- entry ---------- */

/* Result handed back from the worker thread to main. */
typedef struct {
  uint64_t cycles;
  uint64_t hash;
  int rc;
} merlin_worker_result_t;

static merlin_worker_result_t g_worker_result;

/* Worker thread entry: runs the actual IREE inference on the target hart.
 * Zephyr's k_thread_cpu_pin only works on threads created (and not yet
 * started) via k_thread_create; the main cooperative thread on the boot
 * hart cannot be migrated. So for hart 1 backends (rvv, opu) we spawn a
 * pinned worker; for hart 0 backends (scalar, gemmini) main itself is
 * already on hart 0 and could run inline, but going through the worker
 * unconditionally keeps the code path uniform. */
static void merlin_worker_entry(void *a, void *b, void *c) {
  (void)a; (void)b; (void)c;
  int hart_now = arch_curr_cpu()->id;
  if (hart_now != MERLIN_HART) {
    printk("[merlin] WARN: worker landed on wrong hart\n");
  }
  /* lesson 4+5 (2026-05-25): enable mstatus.VS=Dirty for vector backends
   * AND mstatus.XS=Dirty for gemmini LOOP_WS opcodes. set_vs_dirty() sets
   * both bits — call unconditionally; clearing VS for non-V backends is
   * harmless. */
  set_vs_dirty();
  /* Program Gemmini's 8-counter panel before any dispatch runs.
   * Header expands to a no-op shim when MERLIN_PROFILE_COUNTERS is
   * unset, so this is safe to call unconditionally. */
  merlin_gemmini_counter_panel_init();
  g_worker_result.rc = run_inference(&g_worker_result.cycles,
                                     &g_worker_result.hash);
}

/* 2026-05-22: bumped from 64 KiB to 4 MiB. IREE's dispatch_2 for dronet's
 * matmul_3136x32x27 emits ~401 KiB of stack allocas in the prologue (M=3136
 * × bookkeeping for the outer-M tile loop). With 64 KiB the worker thread
 * blows the stack inside the dispatch ELF and Zephyr hangs in fault path.
 * See project_dronet_gemmini_resolved_stack_overflow.md for the original
 * diagnosis. 4 MiB has headroom for yolov8n's larger conv-stack dispatches
 * too. */
#define MERLIN_WORKER_STACK_SIZE (4 * 1024 * 1024)
K_THREAD_STACK_DEFINE(merlin_worker_stack, MERLIN_WORKER_STACK_SIZE);
static struct k_thread merlin_worker_thread;

int main(void) {
  merlin_phase_stamp(PHASE_MAIN_ENTRY);
/* banner print stripped 2026-05-23 */
  printf("model=%s backend=%s hart=%d needs_vector=%d\n",
         MERLIN_MODEL_NAME, MERLIN_BACKEND, MERLIN_HART, MERLIN_NEEDS_VECTOR);

  /* Spawn a worker thread pinned to MERLIN_HART. cpu_pin must be set
   * BEFORE k_thread_start; create-suspended via K_FOREVER + start lets us
   * do that. SCHED_CPU_MASK + SCHED_CPU_MASK_PIN_ONLY are enabled in
   * prj.conf. */
  /* Cooperative priority — Zephyr won't context-switch this thread away
   * unless it explicitly yields/blocks. Critical for the V backend on
   * hart 1: mstatus.VS=Dirty is set once at thread entry; a preempting
   * scheduler would save/restore mstatus per the thread's CONFIG view
   * (which doesn't know about V on hart 1), clearing VS. With COOP, the
   * worker holds the hart for the duration of the IREE invocation. */
  k_tid_t worker = k_thread_create(
      &merlin_worker_thread, merlin_worker_stack, MERLIN_WORKER_STACK_SIZE,
      merlin_worker_entry, NULL, NULL, NULL,
      /*prio=*/K_PRIO_COOP(0), /*opts=*/0, /*delay=*/K_FOREVER);
  int pin_rc = k_thread_cpu_pin(worker, MERLIN_HART);
  if (pin_rc != 0) {
    printf("[merlin] FAIL: k_thread_cpu_pin returned %d\n", pin_rc);
    sys_reboot(SYS_REBOOT_COLD);
    return 1;
  }
  merlin_phase_stamp(PHASE_WORKER_STARTED);
  k_thread_start(worker);
  k_thread_join(worker, K_FOREVER);
  merlin_phase_stamp(PHASE_MAIN_EXIT);

  /* Single line, machine-parseable, sorts well in a CSV. */
  printf("[merlin] result model=%s backend=%s hart=%d cycles=%llu hash=0x%016llx rc=%d\n",
         MERLIN_MODEL_NAME, MERLIN_BACKEND, MERLIN_HART,
         (unsigned long long)g_worker_result.cycles,
         (unsigned long long)g_worker_result.hash, g_worker_result.rc);

  /* 2026-05-23: emit one compact CYC line per dispatch ordinal by walking
   * the loader's per-ordinal accumulators directly. iree_merlin_dump_cycles()
   * in the archive crashes on Zephyr (fprintf(stdout) -> unaligned load on
   * picolibc-without-init); doing it from main.c via plain printf goes
   * through our fprintf shim cleanly. */
  extern uint64_t iree_merlin_cycles_per_ordinal[];
  extern uint64_t iree_merlin_wg_count_per_ordinal[];
  extern const char *iree_merlin_sym_per_ordinal[];
  extern uint32_t iree_merlin_max_ordinal_seen;
  printf("CYC, begin\n");
  for (uint32_t o = 0; o <= iree_merlin_max_ordinal_seen && o < 1024; ++o) {
    uint64_t wg = iree_merlin_wg_count_per_ordinal[o];
    if (wg == 0) continue;
    const char *sym = iree_merlin_sym_per_ordinal[o];
    if (!sym) sym = "(unknown)";
    printf("CYC, %u, %s, %llu, %llu\n", (unsigned)o, sym,
           (unsigned long long)iree_merlin_cycles_per_ordinal[o],
           (unsigned long long)wg);
  }
  printf("CYC, end\n");

#if defined(MERLIN_PROFILE_COUNTERS) && MERLIN_PROFILE_COUNTERS
  /* Per-dispatch Gemmini hardware counter dump. 8 slots per ordinal;
   * panel programmed at worker startup. parse_counters.py decodes the
   * slot index to event name. */
  extern uint64_t iree_merlin_counters_per_ordinal[][8];
  printf("COUNTER, begin\n");
  for (uint32_t o = 0; o <= iree_merlin_max_ordinal_seen && o < 1024; ++o) {
    if (iree_merlin_wg_count_per_ordinal[o] == 0) continue;
    const char *sym = iree_merlin_sym_per_ordinal[o];
    if (!sym) sym = "(unknown)";
    printf("COUNTER, %u, %s", (unsigned)o, sym);
    for (int s = 0; s < 8; ++s) {
      printf(", %llu", (unsigned long long)iree_merlin_counters_per_ordinal[o][s]);
    }
    printf("\n");
  }
  printf("COUNTER, end\n");
#endif

  if (g_worker_result.rc == 0) {
    printf(">>> MERLIN MODEL RUN PASSED <<<\n");
  } else {
    printf(">>> MERLIN MODEL RUN FAILED <<<\n");
  }
  sys_reboot(SYS_REBOOT_COLD);
  return g_worker_result.rc == 0 ? 0 : 1;
}
